/// Sentinel for "this threshold can never be reached".
pub const NEVER: u16 = 0xffff;

bitflags::bitflags! {
    /// Tag bits for ITEM_TAGS. Bit order is fixed by
    /// tools/contentc/schema/item.ts.
    #[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
    pub struct ItemTag: u32 {
        const ORE = 1 << 0;
        const BAR = 1 << 1;
        const GEM = 1 << 2;
        const STONE = 1 << 3;
        const SOIL = 1 << 4;
        const WOOD = 1 << 5;
        const PLANT = 1 << 6;
        const ICE = 1 << 7;
        const FUEL = 1 << 8;
        const PICKAXE = 1 << 9;
        const SWORD = 1 << 10;
        const FOOD = 1 << 11;
        const RELIC = 1 << 12;
        const BUILDABLE = 1 << 13;
        const BOW = 1 << 14;
        const AMMO = 1 << 15;
        const LIGHT = 1 << 16;
    }
}

// Flat tables, index == code. Built by the compiler, not at startup:
// the sim, renderer and collision read these in per-cell loops, and an
// array read is far cheaper than a map hit plus a struct deref.

